import json
import os
import subprocess
import sys
from ahclaude_plugin.secure_api import activate_token

AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
AUTH_CACHE_FILE = os.path.join(AHCLAUDE_DIR, "auth.json")


def load_auth_cache() -> dict:
    if not os.path.exists(AUTH_CACHE_FILE):
        return {}
    try:
        with open(AUTH_CACHE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


_ACTIVATE_STAMP_FILE = os.path.join(AHCLAUDE_DIR, "last_activate")
_ACTIVATE_THROTTLE_SEC = 60


def _activate_debug(msg: str):
    # Hook stderr 在 Claude Code/Codex 中不会污染会话，便于排查激活问题。
    try:
        print(f"[ahclaude.activate] {msg}", file=sys.stderr, flush=True)
    except Exception:
        pass


def _touch_activate_stamp():
    try:
        os.makedirs(AHCLAUDE_DIR, exist_ok=True)
        with open(_ACTIVATE_STAMP_FILE, "w", encoding="utf-8") as f:
            f.write(str(int(__import__("time").time())))
    except Exception:
        pass


def activate_token_with_log(token: str, *, source: str = "unknown"):
    from ahclaude_plugin.hook.logger import hook_log
    short = token[:8] if token else ""
    _activate_debug(f"{source} 调用 activate (token={short}...)")
    try:
        result = activate_token(token)
        code = result.get("code")
        msg = result.get("msg")
        if code == 0:
            hook_log("api", f"activate成功: token={short}... source={source}", extra={"code": 0, "msg": msg, "source": source})
            _touch_activate_stamp()
            _activate_debug(f"{source} 成功: msg={msg}")
        else:
            hook_log("api", f"activate失败: {msg} source={source}", extra={"code": code, "msg": msg, "source": source})
            _activate_debug(f"{source} 失败: code={code} msg={msg}")
    except Exception as e:
        hook_log("api", f"activate异常: {e} source={source}", extra={"error": str(e), "source": source})
        _activate_debug(f"{source} 异常: {e}")


def handle_activate():
    """PreToolUse 钩子：发送请求前确保 token 处于激活状态。

    场景：Claude/Codex 弹出审批弹窗后用户长时间未选择，超过服务端
    inactivity_threshold_minutes 后 key 失活，用户点确认继续时请求即报错。
    在工具执行（紧接着的模型请求）前重新激活即可避免。节流 60s，避免
    单轮多次工具调用时频繁打服务端。

    节流戳记由 `activate_token_with_log` 在成功后写入，因此 prompt/start
    刚激活过的话，PreToolUse 不会再重复打服务端。
    """
    import time

    try:
        now = time.time()
        try:
            last = os.path.getmtime(_ACTIVATE_STAMP_FILE)
            if now - last < _ACTIVATE_THROTTLE_SEC:
                _activate_debug(f"PreToolUse 节流跳过 (距上次 {int(now - last)}s < {_ACTIVATE_THROTTLE_SEC}s)")
                return
        except OSError:
            pass

        auth = load_auth_cache()
        token = auth.get("token", auth.get("api_key", ""))
        if not token:
            _activate_debug("PreToolUse 未找到 token，跳过")
            return
        from ahclaude_plugin.hook.logger import hook_log
        from ahclaude_plugin.hook.codex_auth import ensure_codex_apikey_auth
        if ensure_codex_apikey_auth(token):
            hook_log("auth", "已修复 Codex auth.json 为 apikey 模式，清理 ChatGPT tokens")
            _activate_debug("已修复 Codex auth.json 为 apikey 模式")
        activate_token_with_log(token, source="PreToolUse")
    except Exception as e:
        _activate_debug(f"PreToolUse 异常: {e}")


def _capture_git_snapshot(cwd: str) -> tuple[str, list[str]]:
    if not cwd or not os.path.isdir(cwd):
        return '', []
    try:
        git_dir = subprocess.run(
            ['git', 'rev-parse', '--show-toplevel'],
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=5,
        )
        if git_dir.returncode != 0:
            return '', []

        diff_result = subprocess.run(
            ['git', 'diff', '--no-ext-diff', '--unified=0', '--', '.'],
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=10,
        )
        status_result = subprocess.run(
            ['git', 'ls-files', '--others', '--exclude-standard'],
            cwd=cwd,
            capture_output=True,
            text=True,
            timeout=5,
        )
        diff = diff_result.stdout if diff_result.returncode == 0 else ''
        untracked = status_result.stdout.splitlines() if status_result.returncode == 0 else []
        return diff, untracked
    except Exception:
        return '', []


def handle_prompt(emit_output=True):
    from ahclaude_plugin.hook.logger import hook_log

    try:
        raw = sys.stdin.buffer.read()
        input_data = json.loads(raw.decode('utf-8'))
    except Exception as e:
        hook_log("error", f"cmd_prompt JSON解析失败: {e}")
        return

    session_id = input_data.get("session_id", "")
    prompt = input_data.get("prompt", "")

    # 先激活 key，确保在任何耗时操作之前完成激活
    if session_id:
        try:
            auth = load_auth_cache()
            token = auth.get("token", auth.get("api_key", ""))
            if token:
                from ahclaude_plugin.hook.codex_auth import ensure_codex_apikey_auth
                if ensure_codex_apikey_auth(token):
                    hook_log("auth", "已修复 Codex auth.json 为 apikey 模式，清理 ChatGPT tokens", session_id=session_id)
                activate_token_with_log(token, source="UserPromptSubmit")
        except Exception:
            pass

    if not session_id or not prompt or not prompt.strip():
        return
    
    try:
        from ahclaude_plugin.hook.logger import hook_log_raw
        from ahclaude_plugin.session_cache import increment_turn, get_session_info, set_turn_git_snapshot
        
        turn = increment_turn(session_id, prompt)
        hook_log("prompt", f"[turn:{turn}] {prompt[:50]}...", session_id=session_id)
        hook_log_raw("prompt", input_data)
        info = get_session_info(session_id)
        session_seq = info["session_seq"]
        cwd = input_data.get("cwd", "")
        # 记录本轮开始前的 git 状态，Stop 时补采集 shell 写入产生的 diff。
        before_diff, before_untracked = _capture_git_snapshot(cwd)
        set_turn_git_snapshot(session_id, cwd, before_diff, before_untracked)

        from ahclaude_plugin.hook.report_helper import report_adoption_for_prompt
        report_adoption_for_prompt(
            session_id,
            model_name=input_data.get("model"),
            session_seq=session_seq,
            turn=turn,
            repository_path=cwd,
        )
    except Exception as e:
        hook_log("error", f"cmd_prompt 处理失败: {e}")

    if emit_output == "codex" or emit_output is True:
        print(json.dumps({
            "hookSpecificOutput": {
                "hookEventName": "UserPromptSubmit",
                "additionalContext": ""
            }
        }))


MOCK_PROMPT_INPUT = {
    "session_id": "test-session-123",
    "transcript_path": "/Users/test/.claude/projects/test/test.jsonl",
    "cwd": "/Users/test/project",
    "permission_mode": "default",
    "hook_event_name": "UserPromptSubmit",
    "prompt": "Please fix the bug in utils.py"
}


def test_main():
    print("Running with mock data...")
    input_data = MOCK_PROMPT_INPUT
    print(f"DEBUG prompt input: {json.dumps(input_data, ensure_ascii=False)}", file=sys.stderr)
    
    session_id = input_data.get("session_id", "")
    prompt = input_data.get("prompt", "")
    
    from ahclaude_plugin.hook.logger import hook_log_raw
    hook_log_raw("prompt", input_data)
    
    print(f"Test completed. Check log file: ~/.ahdev/hook.log")


if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == "--test":
        test_main()
    else:
        handle_prompt()
